const turnosAtascados = `-- name: TurnosAtascados :many
SELECT DISTINCT conversacion_id FROM mensajeria.asistente_turnos WHERE estado = 'en_curso' AND tomado_en < $1 ORDER BY conversacion_id LIMIT 50
`

// Turnos que quedaron en curso sin un job que los corra (el job murió): se vuelven a encolar.
func (q *Queries) TurnosAtascados(ctx context.Context, antes time.Time) ([]int64, error) {
	rows, err := q.db.Query(ctx, turnosAtascados, antes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var conversacion_id int64
		if err := rows.Scan(&conversacion_id); err != nil {
			return nil, err
		}
		items = append(items, conversacion_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

